+  border: 1px solid rgba(11,13,20,0.12);
+  background: rgba(255,255,255,0.76);
+}
+.panel .link:hover{ text-decoration: none; background: rgba(118,56,250,0.10); }
+
+.feature-panel::before{
+  content: "";
+  position: absolute;
+  inset: -2px;
+  background:
+    radial-gradient(380px 240px at 15% 25%, rgba(118,56,250,0.22), transparent 60%),
+    radial-gradient(420px 280px at 80% 20%, rgba(255,61,139,0.16), transparent 62%);
+  pointer-events: none;
+}
+.safety-panel{
+  background:
+    radial-gradient(500px 240px at 20% 20%, rgba(17,211,255,0.12), transparent 70%),
+    radial-gradient(520px 280px at 85% 25%, rgba(118,56,250,0.10), transparent 70%),
+    rgba(255,255,255,0.82);
+}
+.creator-panel{
+  background:
+    radial-gradient(520px 260px at 20% 25%, rgba(255,122,0,0.16), transparent 70%),
+    radial-gradient(520px 280px at 85% 30%, rgba(255,61,139,0.14), transparent 70%),
