+
+/* Tagline banner */
+.banner{
+  padding: 28px 0;
+}
+.banner-inner{
+  border-radius: var(--radius-xl);
+  border: 1px solid rgba(11,13,20,0.10);
+  background: linear-gradient(135deg, rgba(118,56,250,0.14), rgba(255,61,139,0.12), rgba(255,122,0,0.14));
