+  align-items: center;
+  justify-content: space-between;
+  gap: 16px;
+  overflow: hidden;
+  position: relative;
+}
+.banner-inner::after{
+  content: "";
+  position: absolute;
+  inset: -2px;
+  background:
+    radial-gradient(340px 220px at 20% 20%, rgba(118,56,250,0.18), transparent 65%),
