+.banner-text{ position: relative; font-weight: 850; letter-spacing: -0.03em; font-size: clamp(18px, 2.1vw, 26px); }
+.banner-meta{ position: relative; color: rgba(11,13,20,0.70); font-weight: 650; font-size: 13px; }
