+/* News carousel */
+.news-top{
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: 16px;
+}
+.news-label{ font-weight: 800; letter-spacing: -0.02em; color: rgba(11,13,20,0.74); }
+.news-title{ margin: 8px 0 0 0; font-size: clamp(22px, 2.4vw, 34px); letter-spacing: -0.03em; }
+
+.news-actions{ display: flex; align-items: center; gap: 10px; }
+.ghost-link{
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 10px 12px;
+  border-radius: 999px;
+  border: 1px solid rgba(11,13,20,0.12);
+  background: rgba(255,255,255,0.68);
+  font-weight: 780;
+}
+.ghost-link:hover{ text-decoration: none; background: rgba(118,56,250,0.10); }
+
+.carousel{
+  margin-top: 18px;
+  position: relative;
+}
+.carousel-viewport{
+  display: flex;
+  gap: 14px;
+  overflow-x: auto;
+  scroll-snap-type: x mandatory;
+  scroll-padding-left: 8px;
+  padding: 8px;
+  margin: 0 -8px;
+  -webkit-overflow-scrolling: touch;
+  scrollbar-width: none;
+}
+.carousel-viewport::-webkit-scrollbar{ display: none; }
+
+.news-card{
+  flex: 0 0 auto;
+  width: min(360px, 84vw);
