+.news-thumb{
+  height: 148px;
+  background: linear-gradient(135deg, rgba(118,56,250,0.34), rgba(255,61,139,0.26), rgba(255,122,0,0.22));
+  position: relative;
+}
+.news-thumb::after{
+  content: "";
+  position: absolute;
+  inset: 0;
+  background:
+    radial-gradient(200px 120px at 20% 30%, rgba(255,255,255,0.30), transparent 65%),
+    radial-gradient(220px 160px at 80% 30%, rgba(17,211,255,0.22), transparent 70%);
+  opacity: 0.9;
+}
+.news-body{ padding: 16px 16px 18px 16px; }
+.tag-row{ display: flex; flex-wrap: wrap; gap: 8px; }
+.tag{
+  font-size: 11px;
+  font-weight: 820;
+  letter-spacing: 0.04em;
+  padding: 7px 10px;
+  border-radius: 999px;
+  border: 1px solid rgba(11,13,20,0.12);
+  background: rgba(255,255,255,0.70);
+  color: rgba(11,13,20,0.74);
+}
+.news-body h3{
+  margin: 12px 0 10px 0;
+  font-size: 16px;
+  line-height: 1.25;
+  letter-spacing: -0.02em;
+}
+.news-meta{ color: rgba(11,13,20,0.60); font-weight: 650; font-size: 12px; }
+
+.carousel-controls{ display: none; }
+
+/* Download CTA */
+.download{
+  padding: 70px 0;
+}
+.download-inner{
+  border-radius: var(--radius-xl);
+  border: 1px solid rgba(11,13,20,0.10);
+  background:
+    radial-gradient(560px 280px at 20% 25%, rgba(118,56,250,0.18), transparent 70%),
+    radial-gradient(560px 300px at 85% 25%, rgba(255,122,0,0.16), transparent 72%),
+    rgba(255,255,255,0.84);
+  box-shadow: var(--shadow);
+  padding: 28px;
+  display: grid;
+  grid-template-columns: 1fr auto;
+  align-items: center;
+  gap: 16px;
+}
+.download h2{ margin: 0; font-size: clamp(22px, 2.5vw, 34px); letter-spacing: -0.03em; }
+.download p{ margin: 8px 0 0 0; color: rgba(11,13,20,0.72); font-weight: 650; }
+.store-buttons{ display: flex; flex-wrap: wrap; gap: 10px; justify-content: flex-end; }
+
+.store{
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  padding: 12px 14px;
+  border-radius: 16px;
+  border: 1px solid rgba(11,13,20,0.12);
+  background: rgba(255,255,255,0.74);
+  font-weight: 780;
+}
+.store:hover{ text-decoration: none; background: rgba(118,56,250,0.10); }
+
+/* Footer */
+footer{
+  padding: 64px 0 34px 0;
+  background:
+    radial-gradient(920px 520px at 30% 0%, rgba(118,56,250,0.12), transparent 60%),
+    radial-gradient(840px 520px at 80% 10%, rgba(255,122,0,0.10), transparent 60%),
+    rgba(251,251,255,0.9);
+  border-top: 1px solid rgba(11,13,20,0.08);
+}
+.footer-top{
+  display: grid;
+  grid-template-columns: 1.1fr 2.2fr;
+  gap: 26px;
+  align-items: start;
+}
+.footer-brand{
+  border-radius: var(--radius-xl);
+  border: 1px solid rgba(11,13,20,0.10);
+  background: rgba(255,255,255,0.78);
+  box-shadow: var(--shadow);
+  padding: 20px;
+}
+.footer-brand p{ margin: 12px 0 0 0; color: rgba(11,13,20,0.70); }
+.footer-grid{
+  display: grid;
+  grid-template-columns: repeat(5, 1fr);
+  gap: 16px;
+}
+.footer-col{
+  border-radius: 18px;
+  border: 1px solid rgba(11,13,20,0.08);
+  background: rgba(255,255,255,0.68);
+  padding: 16px;
+}
+.footer-col h4{ margin: 0 0 10px 0; font-size: 13px; letter-spacing: -0.01em; }
+.footer-col a{
+  display: block;
+  padding: 8px 8px;
+  margin: 0 -8px;
+  border-radius: 12px;
+  color: rgba(11,13,20,0.72);
+  font-weight: 650;
+  font-size: 13px;
+}
+.footer-col a:hover{ text-decoration: none; background: rgba(118,56,250,0.10); color: rgba(11,13,20,0.90); }
+.ext{ display: inline-flex; align-items: center; gap: 8px; }
+.ext svg{ opacity: 0.65; }
+
+.footer-bottom{
+  margin-top: 22px;
+  border-radius: var(--radius-xl);
+  border: 1px solid rgba(11,13,20,0.10);
+  background: rgba(255,255,255,0.78);
+  box-shadow: var(--shadow);
+  padding: 16px;
+  display: grid;
+  grid-template-columns: 1fr auto;
+  gap: 12px;
+  align-items: center;
+}
+.footer-row{
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  align-items: center;
+}
+.select{
+  border: 1px solid rgba(11,13,20,0.12);
+  background: rgba(255,255,255,0.74);
+  border-radius: 14px;
+  padding: 10px 12px;
+  font-weight: 700;
+  color: rgba(11,13,20,0.86);
+}
+.social{
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap;
+}
+.social a{
+  width: 40px;
+  height: 40px;
+  border-radius: 14px;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  border: 1px solid rgba(11,13,20,0.12);
+  background: rgba(255,255,255,0.72);
+}
+.social a:hover{ background: rgba(118,56,250,0.10); }
+
+.legal{
+  display: flex;
+  gap: 10px;
+  flex-wrap: wrap;
+  justify-content: flex-end;
+}
+.legal a{
+  padding: 8px 10px;
+  border-radius: 999px;
+  border: 1px solid rgba(11,13,20,0.10);
+  background: rgba(255,255,255,0.65);
+  color: rgba(11,13,20,0.66);
+  font-weight: 700;
+  font-size: 12px;
+}
+.legal a:hover{ text-decoration: none; background: rgba(118,56,250,0.10); color: rgba(11,13,20,0.84); }
+
+/* Utilities */
+.sr-only{
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+  border: 0;
+}
+
+.pill{
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 8px 10px;
+  border-radius: 999px;
+  border: 1px solid rgba(11,13,20,0.12);
+  background: rgba(255,255,255,0.72);
+  color: rgba(11,13,20,0.74);
+  font-weight: 720;
+  font-size: 12px;
+}
+.pill svg{ opacity: 0.75; }
+
+/* Responsive */
+@media (max-width: 960px){
+  .hero-grid{ grid-template-columns: 1fr; }
+  .split{ grid-template-columns: 1fr; }
+  .footer-top{ grid-template-columns: 1fr; }
+  .footer-grid{ grid-template-columns: repeat(2, 1fr); }
+  .download-inner{ grid-template-columns: 1fr; }
+  .store-buttons{ justify-content: flex-start; }
+}
+
+@media (max-width: 760px){
+  :root{ --header-h: 68px; }
+  .nav{ display: none; }
+  .hamburger{ display: inline-flex; }
+  .stat-row{ grid-template-columns: 1fr; }
+  .bullet-grid{ grid-template-columns: 1fr; }
+  .footer-grid{ grid-template-columns: 1fr; }
+  .footer-bottom{ grid-template-columns: 1fr; }
+  .legal{ justify-content: flex-start; }
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{ scroll-behavior: auto !important; transition: none !important; animation: none !important; }
+}
+
*** End Patch
PATCH"}

